// @ts-nocheck
//
// Berisi biodata lengkap pegawai: NIK, TTL, agama, alamat, email,
// hp, status pernikahan, kepegawaian, jabatan, pendidikan,
// data suami/istri (pasangan) dan anak
// Index by NIP → lookup O(1)

export interface PasanganRecord {
  nama: string;
  status?: string;    // 'Suami' | 'Istri'
  ttl?: string;
  pekerjaan?: string;
}

export interface AnakRecord {
  nama: string;
  ttl?: string;
  status?: string;    // 'Anak Kandung' | 'Anak Tiri' | dst
  tunjangan?: string;
}

export interface BiodataRecord {
  nama?: string;
  nik?: string;
  ttl?: string;
  jk?: string;
  agama?: string;
  perkawinan?: string;
  alamat?: string;
  email?: string;
  hp?: string;
  nip_lama?: string;
  skpd?: string;
  status_kep?: string;
  status_hukum?: string;
  gol?: string;
  sumber_gaji?: string;
  jenis_jabatan?: string;
  nama_jabatan?: string;
  tmt_jabatan?: string;
  tmt_pensiun?: string;
  pdd_jenjang?: string;
  pdd_sekolah?: string;
  pdd_jurusan?: string;
  pdd_lulus?: string;
  tgl_nikah?: string;
  pasangan?: PasanganRecord[];
  anak?: AnakRecord[];
}

